/**
 * Emergency operations plan (EOP) generation.
 *
 * Drafts are generated by the Tier-2 AI capability from the event, its linked
 * hazards, the SOS resource inventory and the operator's additional context.
 * `metadata.generated_by` is `tier2-ai` and records the model, prompt version
 * and token usage.
 *
 * A deterministic, event-specific doctrine draft is still available as an
 * explicit, clearly labelled fallback (`generated_by:
 * "deterministic-fallback"`). It is never used silently: the API returns a
 * typed `503 ai_capability_unavailable` unless the caller opts in, and the
 * fallback itself is never an all-empty skeleton.
 */
import { badGateway } from './errors';
import type { Data } from './filters';

export const EOP_PROMPT_VERSION = 'sos-eop-prompt-v1';
export type EopDraftSource = 'tier2-ai' | 'deterministic-fallback';

export interface DraftContext {
  event: Data;
  hazards: Data[];
  resources: Data[];
  title?: string;
  additionalContext?: string;
  generatedAt?: string;
}

export interface EopAction {
  action_id: string;
  title: string;
  description: string;
  phase: 'prepare' | 'respond' | 'recover';
  priority: 'low' | 'medium' | 'high' | 'critical';
  owner_role: string;
  estimated_minutes: number;
  dependencies: string[];
  required_capability: string;
}

export interface EopAssignment {
  action_id: string;
  resource_unit_id: string | null;
  assignee_id: string | null;
  required_capability: string;
  status: 'pending';
}

export interface EopDraft {
  title: string;
  summary: string;
  status: 'draft';
  version: number;
  objectives: string[];
  operational_phases: string[];
  actions: EopAction[];
  assignment_matrix: EopAssignment[];
  evacuation_plan: string[];
  fallback_plan: string[];
  communications_plan: string[];
  markdown_body: string;
  metadata: Data;
}

const TYPE_LABEL: Record<string, string> = {
  flood: 'lũ lụt',
  storm: 'bão',
  landslide: 'sạt lở',
  fire: 'cháy',
  earthquake: 'động đất',
  outage: 'mất điện',
  pollution: 'ô nhiễm',
  drought: 'hạn hán',
  traffic: 'ùn tắc giao thông',
  epidemic: 'dịch bệnh',
  other: 'sự cố',
};

const SEVERITY_PRIORITY: Record<string, EopAction['priority']> = {
  low: 'low',
  medium: 'medium',
  high: 'high',
  critical: 'critical',
};

const SEVERITY_LABEL: Record<string, string> = {
  low: 'thấp',
  medium: 'trung bình',
  high: 'cao',
  critical: 'nghiêm trọng',
};

interface ActionSeed {
  id: string;
  title: string;
  description: string;
  phase: EopAction['phase'];
  capability: string;
  minutes: number;
  depends?: string[];
}

