function capabilityAvailable(resources: Data[], capability: string): boolean {
  const resourceType = capability === 'medical' ? 'medical_supply' : capability;
  return resources.some((resource) => {
    const status = String(resource.status ?? 'available');
    if (status === 'offline' || status === 'maintenance') return false;
    const type = String(resource.resource_type ?? '');
    if (capability === 'personnel') return type === 'personnel';
    if (capability === 'communications') return type === 'personnel' || type === 'vehicle' || resource.metadata !== undefined;
    return type === resourceType || type === 'personnel' || type === 'vehicle';
  });
}

function actionSeeds(eventType: string): ActionSeed[] {
  const specific = TYPE_ACTIONS[eventType] ?? TYPE_ACTIONS.flood;
  return [...specific, ...COMMON_ACTIONS];
}

function locationText(event: Data): string {
  const location = (event.location as Data | undefined) ?? {};
  return [location.address, location.ward, location.district, location.city]
    .map((value) => (typeof value === 'string' ? value.trim() : ''))
    .filter(Boolean)
    .join(', ');
}

function hazardSummary(hazards: Data[]): string {
  if (hazards.length === 0) return 'Không có lớp cảnh báo liên kết.';
  return hazards
    .slice(0, 5)
    .map((hazard) => `${hazard.title ?? hazard.id} (${hazard.severity ?? 'n/a'})`)
    .join('; ');
}

/** Build a deterministic, event-specific EOP draft. */
export function buildEopDraft(context: DraftContext, version = 1): EopDraft {
  const { event, hazards, resources } = context;
  const eventType = String(event.event_type ?? 'other');
  const severity = String(event.severity ?? 'medium');
  const priority = SEVERITY_PRIORITY[severity] ?? 'medium';
  const typeLabel = TYPE_LABEL[eventType] ?? TYPE_LABEL.other;
  const location = locationText(event);
  const title = context.title?.trim() || `EOP — ${event.title ?? 'Sự kiện khẩn cấp'}`;
  const generatedAt = context.generatedAt ?? new Date().toISOString();
  const seeds = actionSeeds(eventType);

  const actions: EopAction[] = seeds.map((seed) => ({
    action_id: seed.id,
    title: seed.title,
    description: `${seed.description}${location ? ` Khu vực: ${location}.` : ''}`,
    phase: seed.phase,
    priority,
    owner_role: seed.phase === 'recover' ? 'recovery_lead' : seed.phase === 'prepare' ? 'preparedness_lead' : 'operations_lead',
    estimated_minutes: seed.minutes,
    dependencies: seed.depends ?? [],
    required_capability: seed.capability,
  }));

  const assignment_matrix: EopAssignment[] = actions.map((action) => ({
    action_id: action.action_id,
    resource_unit_id: null,
    assignee_id: null,
    required_capability: action.required_capability,
    status: 'pending',
  }));

  const objectives = [
    `Bảo vệ tính mạng người dân tại ${location || 'khu vực ảnh hưởng'} trong tình huống ${typeLabel}.`,
    `Duy trì chỉ huy thống nhất và nhịp báo cáo SITREP 6 giờ/lần ở mức ${SEVERITY_LABEL[severity] ?? severity}.`,
    'Bảo đảm nguồn lực cứu hộ, y tế và nơi trú ẩn được điều phối theo thứ tự ưu tiên.',
    'Khôi phục dịch vụ thiết yếu và hoàn tất AAR trong vòng 72 giờ sau khi kết thúc.',
  ];

  const capabilityGaps = [...new Set(actions.map((action) => action.required_capability))]
    .filter((capability) => !capabilityAvailable(resources, capability));

  const evacuation_plan = [
    `Xác định khu vực ưu tiên sơ tán: ${location || 'theo bản đồ nguy cơ SOS'}.`,
    `Bố trí nơi trú ẩn cho ${Number((event.estimated_impact as Data | undefined)?.evacuated_people) || 'toàn bộ'} người dân trong vùng ảnh hưởng.`,
    'Ưu tiên người già, trẻ em, người khuyết tật và hộ dân tại khu vực ngập sâu/sạt lở.',
    'Bảo đảm tuyến sơ tán không trùng với điểm phong tỏa và có phương án dự phòng.',
  ];

  const fallback_plan = [
    'Nếu mất liên lạc, chuyển sang kênh vô tuyến dự phòng và cử liên lạc viên tới hiện trường.',
    'Nếu thiếu nguồn lực tại chỗ, điều động từ quận/huyện lân cận theo thứ tự ưu tiên đã duyệt.',
    'Nếu điều kiện thời tiết xấu, tạm dừng hoạt động ngoài trời và duy trì cứu hộ khẩn cấp.',
  ];

  const communications_plan = [
    'Phát cảnh báo công khai trên bản đồ SOS, loa phường và tin nhắn khẩn cấp.',
    'Duy trì cập nhật SITREP mỗi 6 giờ và báo cáo đột xuất khi có thương vong.',
    'Chỉ định người phát ngôn duy nhất và kiểm soát tin đồn trên mạng xã hội.',
  ];

  const metadata: Data = {
    generated_by: 'deterministic-fallback',
    generated_at: generatedAt,
    generator: 'sos-eop-doctrine-v1',
    prompt_version: null,
    ai_provider: null,
    model: null,
    source_refs: {
      emergency_event_id: event.id,
      hazard_ids: hazards.map((hazard) => String(hazard.id)),
      resource_unit_ids: resources.map((resource) => String(resource.id)),
    },
    additional_context: context.additionalContext ?? null,
    capability_gaps: capabilityGaps,
  };

  const draft: EopDraft = {
    title,
    summary: `Kế hoạch ứng phó ${typeLabel} cho ${event.title ?? 'sự kiện khẩn cấp'}${location ? ` tại ${location}` : ''}.`,
    status: 'draft',
    version,
    objectives,
    operational_phases: ['prepare', 'respond', 'recover'],
    actions,
    assignment_matrix,
    evacuation_plan,
    fallback_plan,
    communications_plan,
    markdown_body: '',
    metadata,
  };
  draft.markdown_body = renderEopMarkdown(draft, context);
  return draft;
}

/** Render the operator-facing Markdown body for any draft (AI or fallback). */
export function renderEopMarkdown(draft: EopDraft, context: DraftContext): string {
  const { event, hazards, resources } = context;
  const location = locationText(event);
  const metadata = draft.metadata;
  const generatedBy = String(metadata.generated_by ?? 'deterministic-fallback');
  const model = metadata.model ? String(metadata.model) : null;
  const generatedAt = String(metadata.generated_at ?? new Date().toISOString());
  const capabilityGaps = Array.isArray(metadata.capability_gaps)
    ? metadata.capability_gaps.map((gap) => String(gap))
    : [];

  const resourceLines = resources.length === 0
    ? ['Chưa có nguồn lực SOS trong hệ thống — cần bổ sung trước khi submit.']
    : resources.slice(0, 8).map((resource) => `- ${resource.name ?? resource.id}: ${resource.status ?? 'unknown'} · ${resource.resource_type ?? 'n/a'} · ${resource.district ?? 'chưa rõ khu vực'}`);

  const sourceLine = generatedBy === 'tier2-ai'
    ? `AI (${model ?? 'tier-2 model'}) · prompt ${String(metadata.prompt_version ?? EOP_PROMPT_VERSION)}`
    : 'deterministic-fallback (không có AI)';

  return [
    `# ${draft.title}`,
    '',
    `- Sự kiện: ${event.event_code ?? event.id} — ${event.title ?? ''}`,
    `- Loại: ${TYPE_LABEL[String(event.event_type ?? 'other')] ?? TYPE_LABEL.other}; mức độ: ${SEVERITY_LABEL[String(event.severity ?? 'medium')] ?? String(event.severity ?? 'medium')}`,
    `- Địa điểm: ${location || 'chưa xác định'}`,
    `- Cảnh báo liên kết: ${hazardSummary(hazards)}`,
    `- Bản nháp: v${draft.version} · tạo lúc ${generatedAt} · nguồn: ${sourceLine}`,
    '',
    '## Mục tiêu',
    ...draft.objectives.map((objective) => `- ${objective}`),
    '',
    '## Hành động',
    ...draft.actions.map((action) => `- [${action.phase}] ${action.title} — ${action.description} (${action.estimated_minutes} phút)`),
    '',
    '## Ma trận phân công',
    ...draft.assignment_matrix.map((assignment) => `- ${assignment.action_id}: ${assignment.required_capability} (${assignment.status})`),
    '',
    '## Sơ tán',
    ...draft.evacuation_plan.map((line) => `- ${line}`),
    '',
    '## Phương án dự phòng',
    ...draft.fallback_plan.map((line) => `- ${line}`),
    '',
    '## Truyền thông',
    ...draft.communications_plan.map((line) => `- ${line}`),
    '',
    '## Nguồn lực hiện có',
    ...resourceLines,
    '',
    '## Thiếu hụt năng lực',
    ...(capabilityGaps.length ? capabilityGaps.map((gap) => `- ${gap}`) : ['- Không phát hiện thiếu hụt từ danh mục hiện tại.']),
    '',
    context.additionalContext?.trim() ? '## Ghi chú bổ sung' : '',
    context.additionalContext?.trim() || '',
  ].filter((line) => line !== '').join('\n');
}

export interface AiEopPayload {
  summary?: unknown;
  objectives?: unknown;
  operational_phases?: unknown;
  actions?: unknown;
  evacuation_plan?: unknown;
  fallback_plan?: unknown;
  communications_plan?: unknown;
  assignment_matrix?: unknown;
}

export interface AiDraftMeta {
  model: string | null;
  promptVersion: string;
  generatedAt: string;
  usage?: Record<string, unknown> | null;
  provider?: string;
}

const PHASES: ReadonlyArray<EopAction['phase']> = ['prepare', 'respond', 'recover'];
const PRIORITIES: ReadonlyArray<EopAction['priority']> = ['low', 'medium', 'high', 'critical'];

function stringList(value: unknown, maxItems: number): string[] {
  if (!Array.isArray(value)) return [];
  return value
    .map((entry) => (typeof entry === 'string' ? entry.trim() : ''))
    .filter(Boolean)
    .slice(0, maxItems);
}

function slug(value: string, fallback: string): string {
  const safe = value
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 60);
  return safe || fallback;
}

function phaseOf(value: unknown, title: string): EopAction['phase'] {
  const raw = String(value ?? '').toLowerCase();
  if (PHASES.includes(raw as EopAction['phase'])) return raw as EopAction['phase'];
  const text = title.toLowerCase();
  if (/phục hồi|khôi phục|đánh giá|recover|assess|restore/.test(text)) return 'recover';
  if (/chuẩn bị|gia cố|prepare|secure/.test(text)) return 'prepare';
  return 'respond';
}

function priorityOf(value: unknown, fallback: EopAction['priority']): EopAction['priority'] {
  const raw = String(value ?? '').toLowerCase();
  return PRIORITIES.includes(raw as EopAction['priority']) ? raw as EopAction['priority'] : fallback;
}

export function buildEopPrompt(context: DraftContext): Array<{ role: 'system' | 'user'; content: string }> {
  const { event, hazards, resources } = context;
  const eventType = String(event.event_type ?? 'other');
  const compact = {
    event: {
      id: event.id,
      event_code: event.event_code ?? null,
      title: event.title ?? null,
      event_type: eventType,
      severity: event.severity ?? 'medium',
      status: event.status ?? null,
      started_at: event.started_at ?? null,
      location: event.location ?? null,
      estimated_impact: event.estimated_impact ?? null,
      affected_asset_ids: Array.isArray(event.affected_asset_ids) ? event.affected_asset_ids.slice(0, 20) : [],
    },
    linked_hazards: hazards.slice(0, 10).map((hazard) => ({
      id: hazard.id,
      hazard_id: hazard.hazard_id ?? null,
      title: hazard.title ?? null,
      event_type: hazard.event_type ?? null,
      severity: hazard.severity ?? null,
      warning_type: hazard.warning_type ?? null,
      warning_level: hazard.warning_level ?? null,
      district: hazard.district ?? null,
      observed_at: hazard.observed_at ?? null,
    })),
    resources: resources.slice(0, 40).map((resource) => ({
      id: resource.id,
      name: resource.name ?? null,
      resource_type: resource.resource_type ?? null,
      status: resource.status ?? null,
      district: resource.district ?? null,
      capacity: resource.capacity ?? null,
      skills: Array.isArray(resource.skills) ? resource.skills.slice(0, 10) : [],
    })),
    additional_context: context.additionalContext ?? null,
  };

  return [
    {
      role: 'system',
      content: [
        'Bạn là chỉ huy tác chiến của hệ thống ứng phó khẩn cấp SynapseCitySOS (Việt Nam).',
        'Hãy soạn một Kế hoạch Ứng phó Khẩn cấp (EOP) thực tế, cụ thể cho sự kiện được cung cấp.',
        'Chỉ trả về JSON hợp lệ, không kèm Markdown hay giải thích, theo đúng schema:',
        '{',
        '  "summary": string,',
        '  "objectives": string[],',
        '  "operational_phases": ("prepare"|"respond"|"recover")[],',
        '  "actions": [{ "action_id": string, "title": string, "description": string,',
        '                "phase": "prepare"|"respond"|"recover",',
        '                "priority": "low"|"medium"|"high"|"critical",',
        '                "owner_role": string, "estimated_minutes": number,',
        '                "dependencies": string[], "required_capability": string }],',
        '  "evacuation_plan": string[],',
        '  "fallback_plan": string[],',
        '  "communications_plan": string[]',
        '}',
        'Yêu cầu: 3-8 mục tiêu; 5-15 hành động có thứ tự ưu tiên, phụ thuộc và thời lượng;',
        'required_capability thuộc: personnel, vehicle, medical_supply, rescue_equipment, shelter, communications.',
        'Không bịa số liệu thương vong; dùng dữ liệu được cung cấp và ghi rõ nếu cần xác minh.',
      ].join('\n'),
    },
    {
      role: 'user',
      content: `Soạn EOP cho sự kiện sau (JSON ngữ cảnh):\n${JSON.stringify(compact)}`,
    },
  ];
}

/**
 * Turn a validated AI payload into a complete draft. Fields the model omitted
 * are filled from the event-specific deterministic doctrine so a partially
 * structured answer never becomes an empty plan.
 */
export function draftFromAiPayload(
  context: DraftContext,
  version: number,
  payload: AiEopPayload,
  meta: AiDraftMeta,
): EopDraft {
  const { event, hazards, resources } = context;
  const severity = String(event.severity ?? 'medium');
  const priority = SEVERITY_PRIORITY[severity] ?? 'medium';
  const base = buildEopDraft(context, version);

  const objectives = stringList(payload.objectives, 12);
  if (objectives.length === 0) {
    throw badGateway('ai_draft_invalid', 'the AI draft did not contain objectives', { field: 'objectives' });
  }

  const rawActions = Array.isArray(payload.actions) ? payload.actions : [];
  const seen = new Set<string>();
  const actions: EopAction[] = [];
  rawActions.slice(0, 40).forEach((raw, index) => {
    if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return;
    const entry = raw as Data;
    const title = String(entry.title ?? '').trim();
    if (!title) return;
    let actionId = slug(String(entry.action_id ?? ''), `action-${index + 1}`);
    if (seen.has(actionId)) actionId = `${actionId}-${index + 1}`;
    seen.add(actionId);
    const phase = phaseOf(entry.phase, title);
    const dependencies = stringList(entry.dependencies, 10).map((dependency) => slug(dependency, dependency));
    actions.push({
      action_id: actionId,
      title: title.slice(0, 240),
      description: String(entry.description ?? '').trim().slice(0, 2000),
      phase,
      priority: priorityOf(entry.priority, priority),
      owner_role: String(entry.owner_role ?? (phase === 'recover' ? 'recovery_lead' : phase === 'prepare' ? 'preparedness_lead' : 'operations_lead')).slice(0, 80),
      estimated_minutes: Math.min(Math.max(Math.round(Number(entry.estimated_minutes) || 60), 5), 24 * 60),
      dependencies: dependencies.filter((dependency) => dependency !== actionId),
      required_capability: String(entry.required_capability ?? 'personnel').trim().slice(0, 64) || 'personnel',
    });
  });
  if (actions.length === 0) {
    throw badGateway('ai_draft_invalid', 'the AI draft did not contain any usable actions', { field: 'actions' });
  }

  const phases = stringList(payload.operational_phases, 6)
    .map((phase) => phase.toLowerCase())
    .filter((phase): phase is EopAction['phase'] => PHASES.includes(phase as EopAction['phase']));
  const operationalPhases = phases.length ? [...new Set(phases)] : base.operational_phases;

  const assignmentMatrix: EopAssignment[] = actions.map((action) => {
    const provided = Array.isArray(payload.assignment_matrix)
      ? payload.assignment_matrix.find((row) => row && typeof row === 'object' && String((row as Data).action_id ?? '') === action.action_id)
      : undefined;
    const row = provided && typeof provided === 'object' ? provided as Data : {};
    const resourceUnitId = typeof row.resource_unit_id === 'string' && row.resource_unit_id.trim() ? row.resource_unit_id.trim() : null;
    return {
      action_id: action.action_id,
      resource_unit_id: resourceUnitId,
      assignee_id: typeof row.assignee_id === 'string' && row.assignee_id.trim() ? row.assignee_id.trim() : null,
      required_capability: action.required_capability,
      status: 'pending',
    };
  });

  const capabilityGaps = [...new Set(actions.map((action) => action.required_capability))]
    .filter((capability) => !capabilityAvailable(resources, capability));

  const generatedAt = meta.generatedAt;
  const metadata: Data = {
    generated_by: 'tier2-ai' as EopDraftSource,
    generated_at: generatedAt,
    generator: 'sos-eop-ai-v1',
    prompt_version: meta.promptVersion,
    ai_provider: meta.provider ?? 'synapsedx',
    model: meta.model,
    usage: meta.usage ?? null,
    source_refs: {
      emergency_event_id: event.id,
      hazard_ids: hazards.map((hazard) => String(hazard.id)),
      resource_unit_ids: resources.map((resource) => String(resource.id)),
    },
    additional_context: context.additionalContext ?? null,
    capability_gaps: capabilityGaps,
  };

  const evacuationPlan = stringList(payload.evacuation_plan, 12);
  const fallbackPlan = stringList(payload.fallback_plan, 12);
  const communicationsPlan = stringList(payload.communications_plan, 12);

  const draft: EopDraft = {
    title: context.title?.trim() || `EOP — ${event.title ?? 'Sự kiện khẩn cấp'}`,
    summary: String(payload.summary ?? '').trim().slice(0, 2000) || base.summary,
    status: 'draft',
    version,
    objectives,
    operational_phases: operationalPhases,
    actions,
    assignment_matrix: assignmentMatrix,
    evacuation_plan: evacuationPlan.length ? evacuationPlan : base.evacuation_plan,
    fallback_plan: fallbackPlan.length ? fallbackPlan : base.fallback_plan,
    communications_plan: communicationsPlan.length ? communicationsPlan : base.communications_plan,
    markdown_body: '',
    metadata,
  };
  draft.markdown_body = renderEopMarkdown(draft, context);
  return draft;
}

export interface PlanOrderSeed {
  action_id: string;
  task_title: string;
  task_description: string;
  priority: string;
  estimated_minutes: number;
  required_capability: string;
  phase: string;
  target_location: unknown;
}

/**
 * Convert approved plan actions to dispatch-order seeds. The plan's explicit
 * `actions` array is authoritative; a plan without actions legitimately
 * produces zero orders.
 */
export function planOrderSeeds(plan: Data): PlanOrderSeed[] {
  const actions = Array.isArray(plan.actions) ? plan.actions : [];
  const targetLocation = (plan.metadata as Data | undefined)?.target_location ?? null;
  return actions
    .filter((action): action is Data => Boolean(action) && typeof action === 'object' && !Array.isArray(action))
    .map((action, index) => {
      const actionId = String(action.action_id ?? action.id ?? `action-${index + 1}`);
      return {
        action_id: actionId,
        task_title: String(action.title ?? `Nhiệm vụ ${actionId}`),
        task_description: String(action.description ?? ''),
        priority: String(action.priority ?? plan.priority ?? 'medium'),
        estimated_minutes: Number(action.estimated_minutes) || 60,
        required_capability: String(action.required_capability ?? 'personnel'),
        phase: String(action.phase ?? 'respond'),
        target_location: action.target_location ?? targetLocation,
      };
    });
}

/** Deterministic dispatch id so a repeated submit cannot duplicate orders. */
export function orderIdFor(planId: string, actionId: string): string {
  const safe = `${planId}-${actionId}`.replace(/[^A-Za-z0-9_.-]/g, '-');
  return `dsp-${safe}`.slice(0, 180);
}
